//! Current native value mappings. These are R/P facts owned by the native
//! session, not model nodes, S spans, target recipes or an acceptance tape.

use super::allocation::Registry;
mod email;
use super::rows::{NativeRows, charge_host};
use super::small_value::SmallValue;
use super::{
    AcceptedFact, AppendKind, BufferId, Context, DSpan, DecodeKind, DefinitionId, Host,
    MappingAccess, NativeNodeId, NativeViolation, PSpan, PayloadId, PayloadKind, RSpan, StageKind,
    SyntaxRole,
};

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum TransformKind {
    Decode(DecodeKind),
    Payload(StageKind),
    SoftBreakToSpace,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ClaimKind {
    Syntax(SyntaxRole),
    Delimiter,
    Code,
    Math(super::MathSyntax),
    FootnoteReference,
    Break,
    Whitespace,
    Link,
    PayloadTrim,
    Table,
    Task,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum HostRole {
    Block,
    Inline,
    MathInput,
    Destination,
    Title,
    FenceInfo,
    ReferenceLabel,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum NativePhase {
    Block,
    Inline,
    Metadata,
}

fn payload_host(role: PayloadKind) -> HostRole {
    match role {
        PayloadKind::Destination => HostRole::Destination,
        PayloadKind::Title => HostRole::Title,
        PayloadKind::FenceInfo => HostRole::FenceInfo,
        PayloadKind::ReferenceLabel => HostRole::ReferenceLabel,
        PayloadKind::AutolinkLabel => HostRole::ReferenceLabel,
    }
}

/// The grammar action and within-action ordinal, independent of the native
/// arena address, current value layout, target order or eventual model ID.
#[derive(Clone, Copy, Debug, Eq, Ord, PartialEq, PartialOrd)]
pub struct ClaimOrder {
    pub action: u64,
    pub within_action: u32,
}

#[derive(Clone, Copy, Debug)]
pub(super) struct BufferPiece {
    pub r: RSpan,
    pub p: PSpan,
    pub kind: AppendKind,
}

/// Association issued by the actual pipe append, only for transformed cells.
#[derive(Clone, Copy, Debug)]
pub(super) struct TablePipeBinding {
    pub destination: RSpan,
    pub claim: usize,
}

#[derive(Debug)]
pub(super) struct BufferMapping {
    pub owner: NativeNodeId,
    pub len: usize,
    pub sealed: bool,
    // Pieces remain only as ancestry used by live values/accepted claims.
    // A Cut is itself an accepted syntax claim; it cannot erase its source.
    pub pieces: SmallValue<BufferPiece>,
}

#[derive(Clone, Copy, Debug)]
pub(super) struct Atom {
    pub source: RSpan,
    pub bytes: usize,
    pub proof: Option<usize>,
    pub hidden_syntax: bool,
}

#[derive(Default, Debug)]
pub(super) struct MappedValue {
    pub atoms: SmallValue<Atom>,
    pub bytes: usize,
    // Actual current position, invalidated by structural edits. Sequential
    // decoder events must not revisit the already finalized prefix.
    cursor_index: usize,
    cursor_byte: usize,
}

#[derive(Clone, Copy, Debug)]
pub(super) struct HostSnapshot {
    pub source: ClaimSource,
    pub utf8_len: usize,
    pub consumed_start: usize,
    pub consumed_end: usize,
    pub payload_role: Option<PayloadKind>,
    pub role: HostRole,
    pub phase: NativePhase,
}

#[derive(Debug)]
pub(super) struct Proof {
    pub kind: TransformKind,
    pub stage: u32,
    pub host: HostSnapshot,
    // Only the connected atoms that this actual transformation consumed.
    // Previous proof IDs reference immutable accepted ancestors, never text
    // regenerated by running a decoder a second time.
    pub input: SmallValue<Atom>,
    pub local_start: usize,
    pub local_end: usize,
    pub result: String,
}

#[derive(Clone, Copy, Debug)]
pub(super) enum ClaimSource {
    P(PSpan),
    R(RSpan),
}

#[derive(Clone, Copy, Debug)]
pub(super) struct Claim {
    pub owner: NativeNodeId,
    pub order: ClaimOrder,
    pub kind: ClaimKind,
    pub source: ClaimSource,
    pub host_len: usize,
    pub role: HostRole,
    pub phase: NativePhase,
}
impl Claim {
    fn new<H: Host>(
        owner: NativeNodeId,
        order: ClaimOrder,
        kind: ClaimKind,
        source: ClaimSource,
        host: HostSnapshot,
        ctx: &mut MappingAccess<'_, H>,
    ) -> Result<Self, H::Error> {
        let (start, end, same_domain) = match (source, host.source) {
            (ClaimSource::P(p), ClaimSource::P(h)) => {
                (p.start, p.end, h.start == 0 && h.end == host.utf8_len)
            }
            (ClaimSource::R(r), ClaimSource::R(h)) => (
                r.start,
                r.end,
                r.buffer == h.buffer && h.start == 0 && h.end == host.utf8_len,
            ),
            _ => return Err(ctx.host.reject(NativeViolation::InvalidProvenance)),
        };
        if !same_domain
            || host.payload_role.is_some()
            || host.consumed_start != start
            || host.consumed_end != end
            || end > host.utf8_len
            || start >= end
        {
            return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
        }
        Ok(Self {
            owner,
            order,
            kind,
            source,
            host_len: host.utf8_len,
            role: host.role,
            phase: host.phase,
        })
    }
    pub fn host(self) -> HostSnapshot {
        let (source, start, end) = match self.source {
            ClaimSource::P(p) => (
                ClaimSource::P(PSpan {
                    start: 0,
                    end: self.host_len,
                }),
                p.start,
                p.end,
            ),
            ClaimSource::R(r) => (
                ClaimSource::R(RSpan {
                    buffer: r.buffer,
                    start: 0,
                    end: self.host_len,
                }),
                r.start,
                r.end,
            ),
        };
        HostSnapshot {
            source,
            utf8_len: self.host_len,
            consumed_start: start,
            consumed_end: end,
            payload_role: None,
            role: self.role,
            phase: self.phase,
        }
    }
}

#[derive(Clone, Copy, Debug, Default)]
pub(super) struct NodeBinding {
    pub birth_parent: Option<NativeNodeId>,
    pub value: Option<std::num::NonZeroU32>,
    pub block: Option<std::num::NonZeroU32>,
    pub syntax: Option<std::num::NonZeroU32>,
    pub terminal: Option<std::num::NonZeroU32>,
}
#[derive(Clone, Copy, Debug, Default)]
pub(super) struct BlockBinding {
    pub start: Option<usize>,
    pub marker: Option<PSpan>,
    pub buffer: Option<BufferId>,
    pub info: Option<PayloadId>,
    pub fence_opening: Option<PSpan>,
    pub fence_closing: Option<PSpan>,
    pub fence_literal: Option<RSpan>,
    pub callout: Option<std::num::NonZeroU32>,
}
#[derive(Clone, Copy, Debug, Default)]
pub(super) struct SyntaxBinding {
    pub syntax: Option<RSpan>,
    pub math: Option<std::num::NonZeroU32>,
    pub footnote_definition: Option<NativeNodeId>,
    pub inline_footnote: Option<std::num::NonZeroU32>,
    pub label: Option<RSpan>,
    pub wiki: Option<super::WikiForm>,
    pub destination: Option<PayloadId>,
    pub title: Option<PayloadId>,
    pub definition: Option<DefinitionId>,
    pub reference_use: bool,
    pub extended: Option<super::g4::ExtendedAccepted>,
}
#[derive(Clone, Copy, Debug)]
pub(super) struct MathBinding {
    pub syntax: super::MathSyntax,
    pub literal_source: RSpan,
}
#[derive(Clone, Copy, Debug)]
pub(super) struct InlineFootnoteBinding {
    pub reference: NativeNodeId,
    pub definition: NativeNodeId,
    pub body: RSpan,
}
#[derive(Clone, Copy, Debug)]
pub(super) struct CalloutBinding {
    pub kind: super::CalloutKind,
    pub disclosure: super::CalloutDisclosure,
    pub marker: PSpan,
    pub title: Option<NativeNodeId>,
}
pub(super) type TerminalBinding = (BufferId, usize, Option<PSpan>);

#[derive(Debug)]
pub(super) struct PayloadBinding {
    pub role: PayloadKind,
    // The tag has meaning only when prefix is present. Keeping this scalar
    // beside role avoids padding every owned (anchor, String) prefix tuple.
    pub prefix_kind: super::GeneratedPrefix,
    pub raw: RSpan,
    pub value: MappedValue,
    pub stage: u32,
    pub stage_len: usize,
    pub prefix: Option<(RSpan, String)>,
}

pub(super) struct Mappings<L> {
    pub has_footnote_definitions: bool,
    pub has_table_of_contents: bool,
    pub g3: super::g3::Storage<L>,
    pub table_pipes: NativeRows<TablePipeBinding, L>,
    pub nodes: NativeRows<NodeBinding, L>,
    pub values: NativeRows<MappedValue, L>,
    pub blocks: NativeRows<BlockBinding, L>,
    pub syntax: NativeRows<SyntaxBinding, L>,
    pub maths: NativeRows<MathBinding, L>,
    pub inline_footnotes: NativeRows<InlineFootnoteBinding, L>,
    pub callouts: NativeRows<CalloutBinding, L>,
    pub terminals: NativeRows<TerminalBinding, L>,
    pub buffers: NativeRows<BufferMapping, L>,
    pub payloads: NativeRows<PayloadBinding, L>,
    pub proofs: NativeRows<Proof, L>,
    pub claims: NativeRows<Claim, L>,
    pub action: u64,
    pub within_action: u32,
}
impl<L> std::fmt::Debug for Mappings<L> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Mappings")
            .field("nodes", &self.nodes)
            .field("claims", &self.claims)
            .finish_non_exhaustive()
    }
}
impl<L> Default for Mappings<L> {
    fn default() -> Self {
        Self {
            has_footnote_definitions: false,
            has_table_of_contents: false,
            g3: super::g3::Storage::default(),
            table_pipes: NativeRows::default(),
            nodes: NativeRows::default(),
            values: NativeRows::default(),
            blocks: NativeRows::default(),
            syntax: NativeRows::default(),
            maths: NativeRows::default(),
            inline_footnotes: NativeRows::default(),
            callouts: NativeRows::default(),
            terminals: NativeRows::default(),
            buffers: NativeRows::default(),
            payloads: NativeRows::default(),
            proofs: NativeRows::default(),
            claims: NativeRows::default(),
            action: 0,
            within_action: 0,
        }
    }
}

impl MappedValue {
    fn mark_retained<H: Host>(
        &self,
        registry: &mut Registry<H::Lease>,
        host: &mut H,
    ) -> Result<(), H::Error> {
        let Self {
            atoms,
            bytes: _,
            cursor_index: _,
            cursor_byte: _,
        } = self;
        atoms.mark(registry, host)
    }
}

impl<L> Mappings<L> {
    /// Exhaustive physical-owner walk, independent of visibility or winner.
    pub(super) fn mark_retained<H: Host<Lease = L>>(
        &self,
        registry: &mut Registry<L>,
        host: &mut H,
    ) -> Result<(), H::Error> {
        let Self {
            has_footnote_definitions: _,
            has_table_of_contents: _,
            g3: _,
            table_pipes: _,
            nodes: _,
            values,
            blocks: _,
            syntax: _,
            maths: _,
            inline_footnotes: _,
            callouts: _,
            terminals: _,
            buffers,
            payloads,
            proofs,
            claims: _,
            action: _,
            within_action: _,
        } = self;
        // The omitted *rows* above are self-leased and their elements are Copy.
        // These bounds make adding an owned heap field a compilation failure.
        fn flat<T: Copy>() {}
        flat::<NodeBinding>();
        flat::<BlockBinding>();
        flat::<SyntaxBinding>();
        flat::<MathBinding>();
        flat::<InlineFootnoteBinding>();
        flat::<CalloutBinding>();
        flat::<TerminalBinding>();
        flat::<Claim>();
        flat::<HostSnapshot>();
        flat::<TablePipeBinding>();
        self.g3.mark_retained();
        flat::<super::g3::Record>();
        flat::<super::g3::AlignmentRecord>();
        values.visit(host, |value, host| value.mark_retained(registry, host))?;
        buffers.visit(host, |buffer, host| {
            let BufferMapping {
                owner: _,
                len: _,
                sealed: _,
                pieces,
            } = buffer;
            pieces.mark(registry, host)
        })?;
        payloads.visit(host, |payload, host| {
            let PayloadBinding {
                role: _,
                prefix_kind: _,
                raw: _,
                value,
                stage: _,
                stage_len: _,
                prefix,
            } = payload;
            value.mark_retained(registry, host)?;
            if let Some((_, text)) = prefix {
                registry.mark_string(text, host)?;
            }
            Ok(())
        })?;
        proofs.visit(host, |proof, host| {
            let Proof {
                kind: _,
                stage: _,
                host: _,
                input,
                local_start: _,
                local_end: _,
                result,
            } = proof;
            input.mark(registry, host)?;
            registry.mark_string(result, host)
        })?;
        Ok(())
    }
}

impl MappedValue {
    /// Delete sorted stage-input runs in one pass, preserving original R
    /// pieces and existing zero-byte delimiter records. No decoder proof is
    /// permitted before this accepted-reference-title preprocessing stage.
    fn hide_runs<H: Host>(
        &mut self,
        runs: &[DSpan],
        ctx: &mut MappingAccess<'_, H>,
    ) -> Result<(), H::Error> {
        if runs.is_empty() {
            return Ok(());
        }
        let mut output = SmallValue::new();
        let mut position = 0usize;
        let mut run_index = 0usize;
        let mut removed = 0usize;
        for atom in &self.atoms {
            ctx.event()?;
            if atom.proof.is_some() {
                return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
            }
            if atom.bytes == 0 {
                output.push(*atom, ctx)?;
                continue;
            }
            if atom.hidden_syntax
                || atom.source.end.checked_sub(atom.source.start) != Some(atom.bytes)
            {
                return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
            }
            let end = position
                .checked_add(atom.bytes)
                .ok_or_else(|| ctx.host.reject(NativeViolation::ArithmeticOverflow))?;
            let mut cursor = position;
            while cursor < end {
                ctx.event()?;
                while run_index < runs.len() && runs[run_index].end <= cursor {
                    ctx.event()?;
                    run_index += 1;
                }
                let current = runs.get(run_index);
                let hidden = current.is_some_and(|run| run.start <= cursor);
                let next = match current {
                    Some(run) if hidden => end.min(run.end),
                    Some(run) => end.min(run.start),
                    None => end,
                };
                if next <= cursor {
                    return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                }
                let start_r = atom
                    .source
                    .start
                    .checked_add(cursor - position)
                    .ok_or_else(|| ctx.host.reject(NativeViolation::ArithmeticOverflow))?;
                let end_r = start_r
                    .checked_add(next - cursor)
                    .ok_or_else(|| ctx.host.reject(NativeViolation::ArithmeticOverflow))?;
                output.push(
                    Atom {
                        source: RSpan {
                            start: start_r,
                            end: end_r,
                            ..atom.source
                        },
                        bytes: if hidden { 0 } else { next - cursor },
                        proof: None,
                        hidden_syntax: hidden,
                    },
                    ctx,
                )?;
                if hidden {
                    removed = removed
                        .checked_add(next - cursor)
                        .ok_or_else(|| ctx.host.reject(NativeViolation::ArithmeticOverflow))?;
                }
                cursor = next;
            }
            position = end;
        }
        if position != self.bytes || runs.last().is_some_and(|run| run.end > position) {
            return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
        }
        let bytes = self
            .bytes
            .checked_sub(removed)
            .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?;
        let old = std::mem::replace(&mut self.atoms, output);
        self.bytes = bytes;
        self.reset_cursor();
        old.discard(ctx)
    }

    fn hide<H: Host>(
        &mut self,
        start: usize,
        end: usize,
        ctx: &mut MappingAccess<'_, H>,
    ) -> Result<(), H::Error> {
        if start >= end || end > self.bytes {
            return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
        }
        let mut output = SmallValue::new();
        let mut cursor = 0usize;
        for atom in &self.atoms {
            ctx.event()?;
            let next = cursor
                .checked_add(atom.bytes)
                .ok_or_else(|| ctx.host.reject(NativeViolation::ArithmeticOverflow))?;
            let a = cursor.max(start);
            let b = next.min(end);
            if a < b {
                if atom.proof.is_some() {
                    return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                }
                if cursor < a {
                    output.push(
                        Atom {
                            source: RSpan {
                                end: atom.source.start + a - cursor,
                                ..atom.source
                            },
                            bytes: a - cursor,
                            proof: None,
                            hidden_syntax: false,
                        },
                        ctx,
                    )?;
                }
                output.push(
                    Atom {
                        source: RSpan {
                            start: atom.source.start + a - cursor,
                            end: atom.source.start + b - cursor,
                            ..atom.source
                        },
                        bytes: 0,
                        proof: None,
                        hidden_syntax: true,
                    },
                    ctx,
                )?;
                if b < next {
                    output.push(
                        Atom {
                            source: RSpan {
                                start: atom.source.start + b - cursor,
                                ..atom.source
                            },
                            bytes: next - b,
                            proof: None,
                            hidden_syntax: false,
                        },
                        ctx,
                    )?;
                }
            } else {
                output.push(*atom, ctx)?;
            }
            cursor = next;
        }
        let old = std::mem::replace(&mut self.atoms, output);
        old.discard(ctx)?;
        self.bytes -= end - start;
        self.reset_cursor();
        Ok(())
    }
    pub(super) fn raw<H: Host>(
        source: RSpan,
        ctx: &mut MappingAccess<'_, H>,
    ) -> Result<Self, H::Error> {
        let bytes = source
            .end
            .checked_sub(source.start)
            .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?;
        let mut atoms = SmallValue::new();
        if bytes != 0 {
            atoms.push(
                Atom {
                    source,
                    bytes,
                    proof: None,
                    hidden_syntax: false,
                },
                ctx,
            )?;
        }
        Ok(Self {
            atoms,
            bytes,
            cursor_index: 0,
            cursor_byte: 0,
        })
    }

    /// Transfers donor mappings in the same native operation as the actual
    /// byte append. The donor no longer owns any of these source atoms.
    pub(super) fn join<H: Host>(
        &mut self,
        donor: &mut Self,
        before: usize,
        coalesce_raw: bool,
        ctx: &mut MappingAccess<'_, H>,
    ) -> Result<(), H::Error> {
        if before != self.bytes {
            return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
        }
        let bytes = self
            .bytes
            .checked_add(donor.bytes)
            .ok_or_else(|| ctx.host.reject(NativeViolation::ArithmeticOverflow))?;
        let donor_atoms = donor.atoms.take();
        for atom in &donor_atoms {
            if coalesce_raw {
                ctx.event()?;
                ctx.scan(2 * std::mem::size_of::<Atom>())?;
                if let Some(last) = self.atoms.last().copied()
                    && last.bytes != 0
                    && atom.bytes != 0
                    && last.proof.is_none()
                    && atom.proof.is_none()
                    && !last.hidden_syntax
                    && !atom.hidden_syntax
                    && last.source.buffer == atom.source.buffer
                    && last.source.end == atom.source.start
                    && last.source.end.checked_sub(last.source.start) == Some(last.bytes)
                    && atom.source.end.checked_sub(atom.source.start) == Some(atom.bytes)
                {
                    let merged_bytes = last
                        .bytes
                        .checked_add(atom.bytes)
                        .ok_or_else(|| ctx.host.reject(NativeViolation::ArithmeticOverflow))?;
                    // SmallValue::push normally enforces this mutation phase.
                    // An in-place boundary update must retain the same guard.
                    ctx.registry.mutable(ctx.host)?;
                    ctx.host
                        .work(super::WorkDelta::Copy(std::mem::size_of::<Atom>() as u64))?;
                    *self.atoms.last_mut().unwrap() = Atom {
                        source: RSpan {
                            end: atom.source.end,
                            ..last.source
                        },
                        bytes: merged_bytes,
                        proof: None,
                        hidden_syntax: false,
                    };
                    continue;
                }
            }
            self.atoms.push(*atom, ctx)?;
        }
        donor_atoms.discard(ctx)?;
        donor.bytes = 0;
        self.bytes = bytes;
        donor.reset_cursor();
        self.reset_cursor();
        Ok(())
    }

    /// Retires removed ordinary mappings. A whole transformed atom cannot be
    /// silently split by a delimiter crop.
    pub(super) fn crop<H: Host>(
        &mut self,
        start: usize,
        end: usize,
        ctx: &mut MappingAccess<'_, H>,
    ) -> Result<(), H::Error> {
        if start > end || end > self.bytes {
            return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
        }
        let mut retained = SmallValue::new();
        let mut cursor = 0usize;
        for atom in &self.atoms {
            ctx.event()?;
            let next = cursor
                .checked_add(atom.bytes)
                .ok_or_else(|| ctx.host.reject(NativeViolation::ArithmeticOverflow))?;
            let a = cursor.max(start);
            let b = next.min(end);
            if a < b || (atom.bytes == 0 && start <= cursor && cursor < end) {
                let mut part = *atom;
                if a != cursor || b != next {
                    if atom.proof.is_some() {
                        return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                    }
                    part.source.start += a - cursor;
                    part.source.end = part.source.start + b - a;
                    part.bytes = b - a;
                }
                retained.push(part, ctx)?;
            }
            cursor = next;
        }
        let old = std::mem::replace(&mut self.atoms, retained);
        old.discard(ctx)?;
        self.bytes = end - start;
        self.reset_cursor();
        Ok(())
    }

    fn reset_cursor(&mut self) {
        self.cursor_index = 0;
        self.cursor_byte = 0;
    }

    /// Replace a contiguous current-map range. Only the real suffix moves;
    /// every move is charged and bounded, including overlapping moves.
    fn replace<H: Host>(
        &mut self,
        start: usize,
        end: usize,
        values: &[Atom],
        ctx: &mut MappingAccess<'_, H>,
    ) -> Result<(), H::Error> {
        if start > end || end > self.atoms.len() {
            return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
        }
        let old_len = self.atoms.len();
        let new_len = old_len
            .checked_sub(end - start)
            .and_then(|n| n.checked_add(values.len()))
            .ok_or_else(|| ctx.host.reject(NativeViolation::ArithmeticOverflow))?;
        let destination = start
            .checked_add(values.len())
            .ok_or_else(|| ctx.host.reject(NativeViolation::ArithmeticOverflow))?;
        if end == old_len {
            // No suffix exists: do not initialize placeholders only to overwrite
            // them. Admit final capacity before truncating the current owner.
            if new_len > old_len {
                self.atoms.ensure(new_len - old_len, ctx)?;
            }
            self.atoms.truncate(start);
            return self.atoms.extend_from_slice(values, ctx);
        }
        if new_len > old_len {
            self.atoms.ensure(new_len - old_len, ctx)?;
            // Initialized placeholders make the overlap-safe destination valid.
            let placeholder = *values
                .first()
                .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?;
            while self.atoms.len() < new_len {
                self.atoms.push(placeholder, ctx)?;
            }
        }
        let batch = 65_536 / std::mem::size_of::<Atom>();
        let tail = old_len - end;
        if destination > end {
            let mut remaining = tail;
            while remaining != 0 {
                let count = remaining.min(batch);
                let offset = remaining - count;
                ctx.event()?;
                ctx.host.work(super::WorkDelta::Copy(
                    (count * std::mem::size_of::<Atom>()) as u64,
                ))?;
                self.atoms
                    .copy_within(end + offset..end + offset + count, destination + offset);
                remaining = offset;
            }
        } else if destination < end {
            let mut offset = 0;
            while offset < tail {
                let count = (tail - offset).min(batch);
                ctx.event()?;
                ctx.host.work(super::WorkDelta::Copy(
                    (count * std::mem::size_of::<Atom>()) as u64,
                ))?;
                self.atoms
                    .copy_within(end + offset..end + offset + count, destination + offset);
                offset += count;
            }
        }
        ctx.event()?;
        ctx.host
            .work(super::WorkDelta::Copy(std::mem::size_of_val(values) as u64))?;
        self.atoms[start..destination].copy_from_slice(values);
        self.atoms.truncate(new_len);
        Ok(())
    }
}

impl<L> Mappings<L> {
    fn node_mut<H: Host<Lease = L>>(
        &mut self,
        id: NativeNodeId,
        ctx: &mut MappingAccess<'_, H>,
    ) -> Result<&mut NodeBinding, H::Error> {
        self.nodes
            .get_mut(id.get() as usize - 1, |bytes| charge_host(ctx.host, bytes))?
            .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))
    }

    fn slot_id<H: Host<Lease = L>>(
        len: usize,
        ctx: &mut MappingAccess<'_, H>,
    ) -> Result<std::num::NonZeroU32, H::Error> {
        len.checked_add(1)
            .and_then(|n| u32::try_from(n).ok())
            .and_then(std::num::NonZeroU32::new)
            .ok_or_else(|| ctx.host.reject(NativeViolation::ArithmeticOverflow))
    }
    fn value_mut<H: Host<Lease = L>>(
        &mut self,
        node: NativeNodeId,
        ctx: &mut MappingAccess<'_, H>,
    ) -> Result<&mut MappedValue, H::Error> {
        let id = match self.node_mut(node, ctx)?.value {
            Some(id) => id,
            None => {
                let id = Self::slot_id(self.values.len(), ctx)?;
                self.values.push(MappedValue::default(), ctx.host)?;
                ctx.host.work(super::WorkDelta::Copy(std::mem::size_of::<
                    Option<std::num::NonZeroU32>,
                >() as u64))?;
                self.node_mut(node, ctx)?.value = Some(id);
                id
            }
        };
        self.values
            .get_mut(id.get() as usize - 1, |bytes| charge_host(ctx.host, bytes))?
            .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))
    }
    fn block_mut<H: Host<Lease = L>>(
        &mut self,
        node: NativeNodeId,
        ctx: &mut MappingAccess<'_, H>,
    ) -> Result<&mut BlockBinding, H::Error> {
        let id = match self.node_mut(node, ctx)?.block {
            Some(id) => id,
            None => {
                let id = Self::slot_id(self.blocks.len(), ctx)?;
                self.blocks.push(BlockBinding::default(), ctx.host)?;
                ctx.host.work(super::WorkDelta::Copy(std::mem::size_of::<
                    Option<std::num::NonZeroU32>,
                >() as u64))?;
                self.node_mut(node, ctx)?.block = Some(id);
                id
            }
        };
        self.blocks
            .get_mut(id.get() as usize - 1, |bytes| charge_host(ctx.host, bytes))?
            .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))
    }
    fn syntax_mut<H: Host<Lease = L>>(
        &mut self,
        node: NativeNodeId,
        ctx: &mut MappingAccess<'_, H>,
    ) -> Result<&mut SyntaxBinding, H::Error> {
        let id = match self.node_mut(node, ctx)?.syntax {
            Some(id) => id,
            None => {
                let id = Self::slot_id(self.syntax.len(), ctx)?;
                self.syntax.push(SyntaxBinding::default(), ctx.host)?;
                ctx.host.work(super::WorkDelta::Copy(std::mem::size_of::<
                    Option<std::num::NonZeroU32>,
                >() as u64))?;
                self.node_mut(node, ctx)?.syntax = Some(id);
                id
            }
        };
        self.syntax
            .get_mut(id.get() as usize - 1, |bytes| charge_host(ctx.host, bytes))?
            .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))
    }
    fn terminal<H: Host<Lease = L>>(
        &mut self,
        node: NativeNodeId,
        ctx: &mut MappingAccess<'_, H>,
    ) -> Result<Option<TerminalBinding>, H::Error> {
        match self.node_mut(node, ctx)?.terminal {
            None => Ok(None),
            Some(id) => self
                .terminals
                .get(id.get() as usize - 1, |bytes| charge_host(ctx.host, bytes))?
                .copied()
                .map(Some)
                .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance)),
        }
    }
    fn set_terminal<H: Host<Lease = L>>(
        &mut self,
        node: NativeNodeId,
        value: TerminalBinding,
        ctx: &mut MappingAccess<'_, H>,
    ) -> Result<(), H::Error> {
        if let Some(id) = self.node_mut(node, ctx)?.terminal {
            *self
                .terminals
                .get_mut(id.get() as usize - 1, |bytes| charge_host(ctx.host, bytes))?
                .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))? = value;
        } else {
            let id = Self::slot_id(self.terminals.len(), ctx)?;
            self.terminals.push(value, ctx.host)?;
            ctx.host.work(super::WorkDelta::Copy(
                std::mem::size_of::<Option<std::num::NonZeroU32>>() as u64,
            ))?;
            self.node_mut(node, ctx)?.terminal = Some(id);
        }
        Ok(())
    }
    fn raw_host<H: Host<Lease = L>>(
        &self,
        span: RSpan,
        ctx: &mut MappingAccess<'_, H>,
    ) -> Result<HostSnapshot, H::Error> {
        let buffer = self
            .buffers
            .get(span.buffer.get() as usize - 1, |bytes| {
                charge_host(ctx.host, bytes)
            })?
            .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?;
        if span.start > span.end || span.end > buffer.len {
            return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
        }
        Ok(HostSnapshot {
            source: ClaimSource::R(RSpan {
                start: 0,
                end: buffer.len,
                ..span
            }),
            utf8_len: buffer.len,
            consumed_start: span.start,
            consumed_end: span.end,
            payload_role: None,
            role: HostRole::Inline,
            phase: NativePhase::Inline,
        })
    }

    fn claim_r<H: Host<Lease = L>>(
        &mut self,
        owner: NativeNodeId,
        span: RSpan,
        kind: ClaimKind,
        ctx: &mut MappingAccess<'_, H>,
    ) -> Result<(), H::Error> {
        if span.start == span.end {
            return Ok(());
        }
        let mut host = self.raw_host(span, ctx)?;
        if matches!(
            kind,
            ClaimKind::Syntax(
                SyntaxRole::ReferenceDefinition
                    | SyntaxRole::BlockWhitespace
                    | SyntaxRole::TableTrim
                    | SyntaxRole::TableSeparator
                    | SyntaxRole::TableDelimiter
                    | SyntaxRole::TableExtraCell
                    | SyntaxRole::TaskWhitespace
            ) | ClaimKind::Table
                | ClaimKind::Task
        ) {
            host.role = HostRole::Block;
            host.phase = NativePhase::Block;
        }
        if matches!(kind, ClaimKind::Math(_)) {
            host.role = HostRole::MathInput;
        }
        let order = ClaimOrder {
            action: self.action,
            within_action: self.within_action,
        };
        self.within_action = self
            .within_action
            .checked_add(1)
            .ok_or_else(|| ctx.host.reject(NativeViolation::ArithmeticOverflow))?;
        self.claims.push(
            Claim::new(owner, order, kind, ClaimSource::R(span), host, ctx)?,
            ctx.host,
        )
    }

    fn claim_p<H: Host<Lease = L>>(
        &mut self,
        owner: NativeNodeId,
        span: PSpan,
        kind: ClaimKind,
        ctx: &mut MappingAccess<'_, H>,
    ) -> Result<(), H::Error> {
        if span.start == span.end {
            return Ok(());
        }
        let order = ClaimOrder {
            action: self.action,
            within_action: self.within_action,
        };
        self.within_action = self
            .within_action
            .checked_add(1)
            .ok_or_else(|| ctx.host.reject(NativeViolation::ArithmeticOverflow))?;
        let host = HostSnapshot {
            source: ClaimSource::P(PSpan {
                start: 0,
                end: ctx.input_len,
            }),
            utf8_len: ctx.input_len,
            consumed_start: span.start,
            consumed_end: span.end,
            payload_role: None,
            role: HostRole::Block,
            phase: NativePhase::Block,
        };
        self.claims.push(
            Claim::new(owner, order, kind, ClaimSource::P(span), host, ctx)?,
            ctx.host,
        )
    }

    fn append_proof_part<H: Host<Lease = L>>(
        &self,
        proof: usize,
        start: usize,
        end: usize,
        output: &mut String,
        ctx: &mut MappingAccess<'_, H>,
    ) -> Result<(), H::Error> {
        let text = self
            .proofs
            .get(proof, |bytes| charge_host(ctx.host, bytes))?
            .and_then(|p| p.result.get(start..end))
            .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?;
        ctx.append(output, text)
    }

    /// Replace only the actually transformed component. Whole prior atoms
    /// that overlap its boundary become ancestors of the new whole atom.
    fn transform<H: Host<Lease = L>>(
        &mut self,
        map: &mut MappedValue,
        start: usize,
        end: usize,
        text: &str,
        kind: TransformKind,
        stage: u32,
        host: HostSnapshot,
        ctx: &mut MappingAccess<'_, H>,
    ) -> Result<(), H::Error> {
        if start >= end || end > map.bytes {
            return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
        }
        if map.cursor_byte > start || map.cursor_index >= map.atoms.len() {
            map.reset_cursor();
        }
        let mut at = map.cursor_index;
        let mut cursor = map.cursor_byte;
        // Keep zero-output atoms at the start boundary before this operation,
        // matching the original before-first ordering.
        while let Some(atom) = map.atoms.get(at) {
            ctx.event()?;
            let next = cursor
                .checked_add(atom.bytes)
                .ok_or_else(|| ctx.host.reject(NativeViolation::ArithmeticOverflow))?;
            if next > start {
                break;
            }
            cursor = next;
            at += 1;
        }
        let first_index = at;
        let first_byte = cursor;
        let mut input = SmallValue::new();
        let mut prefix = String::new();
        let mut suffix = String::new();
        let mut left = None;
        let mut right = None;
        while cursor < end {
            ctx.event()?;
            let atom = map
                .atoms
                .get(at)
                .copied()
                .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?;
            let next = cursor
                .checked_add(atom.bytes)
                .ok_or_else(|| ctx.host.reject(NativeViolation::ArithmeticOverflow))?;
            if atom.bytes == 0 {
                // Only strictly interior zero-output atoms are ancestors.
                input.push(atom, ctx)?;
            } else if let Some(proof) = atom.proof {
                if cursor < start {
                    self.append_proof_part(proof, 0, start - cursor, &mut prefix, ctx)?;
                }
                if next > end {
                    self.append_proof_part(proof, end - cursor, atom.bytes, &mut suffix, ctx)?;
                }
                input.push(atom, ctx)?;
            } else {
                let a = cursor.max(start);
                let b = next.min(end);
                if cursor < a {
                    left = Some(Atom {
                        source: RSpan {
                            end: atom.source.start + a - cursor,
                            ..atom.source
                        },
                        bytes: a - cursor,
                        proof: None,
                        hidden_syntax: false,
                    });
                }
                input.push(
                    Atom {
                        source: RSpan {
                            start: atom.source.start + a - cursor,
                            end: atom.source.start + b - cursor,
                            ..atom.source
                        },
                        bytes: b - a,
                        proof: None,
                        hidden_syntax: false,
                    },
                    ctx,
                )?;
                if b < next {
                    right = Some(Atom {
                        source: RSpan {
                            start: atom.source.start + b - cursor,
                            ..atom.source
                        },
                        bytes: next - b,
                        proof: None,
                        hidden_syntax: false,
                    });
                }
            }
            cursor = next;
            at += 1;
        }
        let first = input
            .first()
            .copied()
            .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?;
        let last = input
            .last()
            .copied()
            .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?;
        if first.source.buffer != last.source.buffer {
            return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
        }
        let source = RSpan {
            end: last.source.end,
            ..first.source
        };
        let local_start = prefix.len();
        let local_end = local_start
            .checked_add(end - start)
            .ok_or_else(|| ctx.host.reject(NativeViolation::ArithmeticOverflow))?;
        ctx.append(&mut prefix, text)?;
        ctx.append(&mut prefix, &suffix)?;
        ctx.discard_string(suffix)?;
        let bytes = prefix.len();
        let proof = self.proofs.len();
        self.proofs.push(
            Proof {
                kind,
                stage,
                host,
                input,
                local_start,
                local_end,
                result: prefix,
            },
            ctx.host,
        )?;
        let replacement = Atom {
            source,
            bytes,
            proof: Some(proof),
            hidden_syntax: false,
        };
        let mut replacements = [replacement; 3];
        let mut count = 0;
        if let Some(left) = left {
            replacements[count] = left;
            count += 1;
        }
        let proof_index = first_index + count;
        let proof_byte = first_byte
            .checked_add(left.map_or(0, |atom| atom.bytes))
            .ok_or_else(|| ctx.host.reject(NativeViolation::ArithmeticOverflow))?;
        replacements[count] = replacement;
        count += 1;
        if let Some(right) = right {
            replacements[count] = right;
            count += 1;
        }
        map.replace(first_index, at, &replacements[..count], ctx)?;
        map.bytes = map
            .bytes
            .checked_sub(end - start)
            .and_then(|n| n.checked_add(text.len()))
            .ok_or_else(|| ctx.host.reject(NativeViolation::ArithmeticOverflow))?;
        map.cursor_index = proof_index;
        map.cursor_byte = proof_byte;
        Ok(())
    }
    pub(super) fn accept<H: Host<Lease = L>>(
        &mut self,
        fact: AcceptedFact<'_>,
        ctx: &mut MappingAccess<'_, H>,
    ) -> Result<(), H::Error> {
        self.action = self
            .action
            .checked_add(1)
            .ok_or_else(|| ctx.host.reject(NativeViolation::ArithmeticOverflow))?;
        self.within_action = 0;
        use AcceptedFact as F;
        match fact {
            F::G3(fact) => {
                self.check_g3(fact, ctx)?;
                self.g3.accept(fact, ctx.host)?;
                if let super::g3::Fact::Task { node, marker, .. } = fact {
                    self.claim_r(node, marker, ClaimKind::Task, ctx)?;
                }
            }
            F::NodeCreated { node, parent, .. } => {
                if node.get() as usize != self.nodes.len() + 1 {
                    return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                }
                self.nodes.push(
                    NodeBinding {
                        birth_parent: parent,
                        ..NodeBinding::default()
                    },
                    ctx.host,
                )?;
                if let F::NodeCreated { kind, .. } = fact
                    && matches!(
                        kind,
                        super::NativeKind::Table
                            | super::NativeKind::TableRow
                            | super::NativeKind::TableCell
                            | super::NativeKind::TaskCheckbox
                    )
                {
                    self.g3.note_kind(node, kind, ctx.host)?;
                }
            }
            F::Retyped { node, kind } => {
                self.node_mut(node, ctx)?;
                if matches!(
                    kind,
                    super::NativeKind::Table
                        | super::NativeKind::TableRow
                        | super::NativeKind::TableCell
                        | super::NativeKind::TaskCheckbox
                ) {
                    self.g3.note_kind(node, kind, ctx.host)?;
                }
            }
            F::BlockStart { node, at } => self.block_mut(node, ctx)?.start = Some(at),
            F::Callout {
                node,
                kind,
                disclosure,
                marker,
                title,
            } => {
                let id = Self::slot_id(self.callouts.len(), ctx)?;
                if marker.start >= marker.end
                    || self.block_mut(node, ctx)?.callout.replace(id).is_some()
                {
                    return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                }
                self.callouts.push(
                    CalloutBinding {
                        kind,
                        disclosure,
                        marker,
                        title,
                    },
                    ctx.host,
                )?;
                self.claim_p(
                    node,
                    marker,
                    ClaimKind::Syntax(SyntaxRole::CalloutMarker),
                    ctx,
                )?;
            }
            F::BlockConsume { .. } => {}
            F::Syntax { node, role, span } => {
                self.claim_p(node, span, ClaimKind::Syntax(role), ctx)?;
                if role == SyntaxRole::FootnoteMarker {
                    self.has_footnote_definitions = true;
                }
                if role == SyntaxRole::TableOfContents {
                    self.has_table_of_contents = true;
                }
                if matches!(role, SyntaxRole::FenceOpening | SyntaxRole::FenceClosing) {
                    let binding = self.block_mut(node, ctx)?;
                    match role {
                        SyntaxRole::FenceOpening => binding.fence_opening = Some(span),
                        SyntaxRole::FenceClosing => binding.fence_closing = Some(span),
                        _ => unreachable!(),
                    }
                }
                if span.start != span.end
                    && matches!(
                        role,
                        SyntaxRole::HeadingPrefix
                            | SyntaxRole::SetextUnderline
                            | SyntaxRole::ListPrefix
                            | SyntaxRole::DescriptionMarker
                            | SyntaxRole::FootnoteMarker
                            | SyntaxRole::FenceOpening
                            | SyntaxRole::CodeIndent
                    )
                {
                    let binding = self.block_mut(node, ctx)?;
                    if binding.marker.is_none() {
                        binding.marker = Some(span);
                    }
                }
            }
            F::BufferCreated { node, buffer } => {
                if buffer.get() as usize != self.buffers.len() + 1 {
                    return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                }
                self.block_mut(node, ctx)?.buffer = Some(buffer);
                self.buffers.push(
                    BufferMapping {
                        owner: node,
                        len: 0,
                        sealed: false,
                        pieces: SmallValue::new(),
                    },
                    ctx.host,
                )?;
            }
            F::Append { span, source, kind } => {
                let buffer = self
                    .buffers
                    .get_mut(span.buffer.get() as usize - 1, |bytes| {
                        charge_host(ctx.host, bytes)
                    })?
                    .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?;
                if buffer.sealed || span.start != buffer.len || span.start > span.end {
                    return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                }
                buffer.pieces.push(
                    BufferPiece {
                        r: span,
                        p: source,
                        kind,
                    },
                    ctx,
                )?;
                buffer.len = span.end;
            }
            F::Cut { span, reason } => {
                let buffer = self
                    .buffers
                    .get(span.buffer.get() as usize - 1, |bytes| {
                        charge_host(ctx.host, bytes)
                    })?
                    .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?;
                let mut owner = buffer.owner;
                if reason == SyntaxRole::TaskWhitespace {
                    owner = self
                        .node_mut(owner, ctx)?
                        .birth_parent
                        .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?;
                }
                self.claim_r(owner, span, ClaimKind::Syntax(reason), ctx)?;
            }
            F::Seal { buffer, len } => {
                let buffer = self
                    .buffers
                    .get_mut(buffer.get() as usize - 1, |bytes| {
                        charge_host(ctx.host, bytes)
                    })?
                    .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?;
                if buffer.len != len {
                    return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                }
                buffer.sealed = true;
            }
            F::TextAccepted { node, span } | F::RawHtml { node, span, .. } => {
                if let Some(id) = self.node_mut(node, ctx)?.block {
                    let block = self
                        .blocks
                        .get_mut(id.get() as usize - 1, |bytes| charge_host(ctx.host, bytes))?
                        .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?;
                    if block.fence_opening.is_some() {
                        block.fence_literal = Some(span);
                    }
                }
                let mut value = MappedValue::raw(span, ctx)?;
                if let Some((buffer, at, None)) = self.terminal(node, ctx)? {
                    let mut terminal = MappedValue::raw(
                        RSpan {
                            buffer,
                            start: at,
                            end: at + 1,
                        },
                        ctx,
                    )?;
                    let before = value.bytes;
                    // The authored terminal is a separate block literal atom.
                    value.join(&mut terminal, before, false, ctx)?;
                }
                *self.value_mut(node, ctx)? = value;
            }
            F::DecodeAtom {
                node,
                source,
                kind,
                value,
            } => {
                let mut map = std::mem::take(self.value_mut(node, ctx)?);
                // TextAccepted initially binds the true raw range. Escaped's
                // child is born at the punctuation, so include the accepted
                // backslash only when the decoder explicitly supplied it.
                if map.atoms.len() == 1
                    && map.atoms[0].proof.is_none()
                    && (source.start < map.atoms[0].source.start
                        || source.end > map.atoms[0].source.end)
                {
                    map.atoms.take().discard(ctx)?;
                    map = MappedValue::raw(source, ctx)?;
                }
                if map.atoms.get(map.cursor_index).is_none_or(|atom| {
                    atom.source.buffer != source.buffer || source.start < atom.source.start
                }) {
                    map.reset_cursor();
                }
                let mut cursor = map.cursor_byte;
                let mut begin = None;
                let mut finish = None;
                for atom in &map.atoms[map.cursor_index..] {
                    ctx.event()?;
                    if atom.source.buffer == source.buffer {
                        if atom.source.start <= source.start && source.start < atom.source.end {
                            if atom.proof.is_some() && source.start != atom.source.start {
                                return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                            }
                            begin = Some(cursor + source.start - atom.source.start);
                        }
                        if atom.source.start < source.end && source.end <= atom.source.end {
                            if atom.proof.is_some() && source.end != atom.source.end {
                                return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                            }
                            finish = Some(
                                cursor
                                    + if atom.proof.is_some() {
                                        atom.bytes
                                    } else {
                                        source.end - atom.source.start
                                    },
                            );
                        }
                    }
                    if begin.is_some() && finish.is_some() {
                        break;
                    }
                    cursor = cursor
                        .checked_add(atom.bytes)
                        .ok_or_else(|| ctx.host.reject(NativeViolation::ArithmeticOverflow))?;
                }
                let begin =
                    begin.ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?;
                let finish =
                    finish.ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?;
                let mut host = self.raw_host(source, ctx)?;
                if let Some(id) = self.node_mut(node, ctx)?.syntax {
                    let syntax = self
                        .syntax
                        .get(id.get() as usize - 1, |n| charge_host(ctx.host, n))?
                        .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?;
                    if let Some(id) = syntax.math {
                        let math = self
                            .maths
                            .get(id.get() as usize - 1, |n| charge_host(ctx.host, n))?
                            .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?;
                        if !matches!(
                            math.syntax,
                            super::MathSyntax::DollarInline | super::MathSyntax::CodeInline
                        ) || !matches!(
                            kind,
                            super::DecodeKind::CodeLineEndingToSpace | super::DecodeKind::CodeTrim
                        ) {
                            return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                        }
                        host.role = HostRole::MathInput;
                    }
                }
                let result = self.transform(
                    &mut map,
                    begin,
                    finish,
                    value,
                    TransformKind::Decode(kind),
                    1,
                    host,
                    ctx,
                );
                *self.value_mut(node, ctx)? = map;
                result?;
            }
            F::TextJoin {
                survivor,
                donor,
                survivor_bytes_before,
            } => {
                if survivor == donor {
                    return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                }
                let mut destination = std::mem::take(self.value_mut(survivor, ctx)?);
                let mut source = std::mem::take(self.value_mut(donor, ctx)?);
                let coalesce_raw = ctx.inline_policy == super::InlinePolicy::StrictG4;
                let result =
                    destination.join(&mut source, survivor_bytes_before, coalesce_raw, ctx);
                *self.value_mut(survivor, ctx)? = destination;
                *self.value_mut(donor, ctx)? = source;
                result?;
            }
            F::Emphasis {
                node,
                opener,
                closer,
                used,
            } => {
                let open = self.value_mut(opener, ctx)?;
                let os = open
                    .atoms
                    .first()
                    .map(|a| a.source)
                    .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?;
                let oe = open.atoms.last().unwrap().source.end;
                let close = self.value_mut(closer, ctx)?;
                let cs = close
                    .atoms
                    .first()
                    .map(|a| a.source)
                    .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?;
                self.claim_r(
                    node,
                    RSpan {
                        start: oe
                            .checked_sub(used)
                            .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?,
                        end: oe,
                        ..os
                    },
                    ClaimKind::Delimiter,
                    ctx,
                )?;
                self.claim_r(
                    node,
                    RSpan {
                        end: cs.start + used,
                        ..cs
                    },
                    ClaimKind::Delimiter,
                    ctx,
                )?;
                let mut open = std::mem::take(self.value_mut(opener, ctx)?);
                let mut close = std::mem::take(self.value_mut(closer, ctx)?);
                let result = (|| {
                    open.crop(
                        0,
                        open.bytes
                            .checked_sub(used)
                            .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?,
                        ctx,
                    )?;
                    close.crop(used, close.bytes, ctx)
                })();
                *self.value_mut(opener, ctx)? = open;
                *self.value_mut(closer, ctx)? = close;
                result?;
            }
            F::Code {
                node,
                syntax,
                delimiter_bytes,
            } => {
                let body = RSpan {
                    start: syntax.start + delimiter_bytes,
                    end: syntax
                        .end
                        .checked_sub(delimiter_bytes)
                        .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?,
                    ..syntax
                };
                let value = MappedValue::raw(body, ctx)?;
                *self.value_mut(node, ctx)? = value;
                self.syntax_mut(node, ctx)?.syntax = Some(syntax);
                self.claim_r(
                    node,
                    RSpan {
                        end: body.start,
                        ..syntax
                    },
                    ClaimKind::Code,
                    ctx,
                )?;
                self.claim_r(
                    node,
                    RSpan {
                        start: body.end,
                        ..syntax
                    },
                    ClaimKind::Code,
                    ctx,
                )?;
            }
            F::HtmlCode { node, syntax, body } => {
                if syntax.buffer != body.buffer
                    || !matches!(body.start.checked_sub(syntax.start), Some(5..=34))
                    || !matches!(syntax.end.checked_sub(body.end), Some(6..=34))
                    || body.start > body.end
                {
                    return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                }
                let opening = RSpan {
                    end: body.start,
                    ..syntax
                };
                let closing = RSpan {
                    start: body.end,
                    ..syntax
                };
                let bytes = body.end - body.start;
                let mut atoms = SmallValue::new();
                atoms.push(
                    Atom {
                        source: opening,
                        bytes: 0,
                        proof: None,
                        hidden_syntax: true,
                    },
                    ctx,
                )?;
                if bytes != 0 {
                    atoms.push(
                        Atom {
                            source: body,
                            bytes,
                            proof: None,
                            hidden_syntax: false,
                        },
                        ctx,
                    )?;
                }
                atoms.push(
                    Atom {
                        source: closing,
                        bytes: 0,
                        proof: None,
                        hidden_syntax: true,
                    },
                    ctx,
                )?;
                *self.value_mut(node, ctx)? = MappedValue {
                    atoms,
                    bytes,
                    cursor_index: 0,
                    cursor_byte: 0,
                };
                self.syntax_mut(node, ctx)?.syntax = Some(syntax);
                self.claim_r(node, opening, ClaimKind::Code, ctx)?;
                self.claim_r(node, closing, ClaimKind::Code, ctx)?;
            }
            F::Math {
                node,
                syntax,
                literal_source,
                delimiter_form,
            } => {
                let delimiters = delimiter_form.delimiter_bytes();
                if syntax.buffer != literal_source.buffer
                    || syntax.start.checked_add(delimiters) != Some(literal_source.start)
                    || literal_source.end.checked_add(delimiters) != Some(syntax.end)
                    || literal_source.start >= literal_source.end
                {
                    return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                }
                let value = MappedValue::raw(literal_source, ctx)?;
                *self.value_mut(node, ctx)? = value;
                let binding = self.syntax_mut(node, ctx)?;
                if binding.syntax.is_some() || binding.math.is_some() {
                    return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                }
                let id = Self::slot_id(self.maths.len(), ctx)?;
                self.maths.push(
                    MathBinding {
                        syntax: delimiter_form,
                        literal_source,
                    },
                    ctx.host,
                )?;
                let binding = self.syntax_mut(node, ctx)?;
                binding.syntax = Some(syntax);
                binding.math = Some(id);
                self.claim_r(node, syntax, ClaimKind::Math(delimiter_form), ctx)?;
            }
            F::FootnoteReference {
                node,
                definition,
                syntax,
            } => {
                let binding = self.syntax_mut(node, ctx)?;
                if binding.syntax.is_some() || binding.footnote_definition.is_some() {
                    return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                }
                binding.syntax = Some(syntax);
                binding.footnote_definition = Some(definition);
                self.claim_r(node, syntax, ClaimKind::FootnoteReference, ctx)?;
            }
            F::InlineFootnote {
                node,
                definition,
                body,
            } => {
                let definition = definition
                    .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?;
                let start = body
                    .start
                    .checked_sub(2)
                    .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?;
                let end = body
                    .end
                    .checked_add(1)
                    .ok_or_else(|| ctx.host.reject(NativeViolation::ArithmeticOverflow))?;
                if node == definition || body.start >= body.end {
                    return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                }
                let id = Self::slot_id(self.inline_footnotes.len(), ctx)?;
                let binding = self.syntax_mut(node, ctx)?;
                if binding.inline_footnote.replace(id).is_some()
                    || binding.footnote_definition.replace(definition).is_some()
                {
                    return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                }
                if self
                    .syntax_mut(definition, ctx)?
                    .inline_footnote
                    .replace(id)
                    .is_some()
                {
                    return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                }
                self.inline_footnotes.push(
                    InlineFootnoteBinding {
                        reference: node,
                        definition,
                        body,
                    },
                    ctx.host,
                )?;
                self.has_footnote_definitions = true;
                self.claim_r(
                    node,
                    RSpan {
                        start,
                        end: body.start,
                        ..body
                    },
                    ClaimKind::FootnoteReference,
                    ctx,
                )?;
                self.claim_r(
                    node,
                    RSpan {
                        start: body.end,
                        end,
                        ..body
                    },
                    ClaimKind::FootnoteReference,
                    ctx,
                )?;
                self.claim_r(
                    definition,
                    body,
                    ClaimKind::Syntax(SyntaxRole::FootnoteContent),
                    ctx,
                )?;
            }
            F::Break {
                node,
                kind,
                marker,
                ending,
                prefix,
            } => {
                let mut value = MappedValue::raw(ending, ctx)?;
                if kind == super::BreakKind::Soft {
                    let bytes = value.bytes;
                    let host = self.raw_host(ending, ctx)?;
                    self.transform(
                        &mut value,
                        0,
                        bytes,
                        " ",
                        TransformKind::SoftBreakToSpace,
                        1,
                        host,
                        ctx,
                    )?;
                }
                *self.value_mut(node, ctx)? = value;
                if let Some(marker) = marker {
                    self.claim_r(node, marker, ClaimKind::Break, ctx)?;
                }
                self.claim_r(node, prefix, ClaimKind::Whitespace, ctx)?;
            }
            F::CodeTerminal {
                node,
                buffer,
                at,
                eof,
            } => self.set_terminal(node, (buffer, at, eof), ctx)?,
            F::BlockPayload { node, payload } => self.block_mut(node, ctx)?.info = Some(payload),
            F::PayloadBegin { payload, role, raw } => {
                if payload.get() as usize != self.payloads.len() + 1 {
                    return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                }
                let value = MappedValue::raw(raw, ctx)?;
                self.payloads.push(
                    PayloadBinding {
                        role,
                        prefix_kind: super::GeneratedPrefix::Http,
                        raw,
                        value,
                        stage: 0,
                        stage_len: raw.end - raw.start,
                        prefix: None,
                    },
                    ctx.host,
                )?;
            }
            F::PayloadPrefix {
                payload,
                kind,
                at,
                value,
            } => {
                ctx.scan(value.len())?;
                if value != kind.text() {
                    return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                }
                let text = ctx.string(value)?;
                let row = self
                    .payloads
                    .get_mut(payload.get() as usize - 1, |bytes| {
                        charge_host(ctx.host, bytes)
                    })?
                    .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?;
                if row.prefix.is_some()
                    || at.buffer != row.raw.buffer
                    || at.start != row.raw.start
                    || at.end != at.start
                {
                    return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                }
                row.prefix_kind = kind;
                row.prefix = Some((at, text));
            }
            F::Stage {
                payload,
                stage,
                kind,
                input,
                output_start,
                output_end,
                value,
                hidden_runs,
            } => {
                if kind == StageKind::ReferenceTitleIndent {
                    let row = self
                        .payloads
                        .get_mut(payload.get() as usize - 1, |bytes| {
                            charge_host(ctx.host, bytes)
                        })?
                        .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?;
                    let input_len = row.value.bytes;
                    if row.role != PayloadKind::Title
                        || stage != 2
                        || row.stage != 1
                        || input.payload != payload
                        || input.stage != 1
                        || input.start != 0
                        || input.end != input_len
                        || output_start != 0
                        || output_end != value.len()
                    {
                        return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                    }
                    let mut previous_end = 0usize;
                    let mut removed = 0usize;
                    for run in hidden_runs {
                        ctx.event()?;
                        if run.payload != payload
                            || run.stage != 1
                            || run.start >= run.end
                            || run.start < previous_end
                            || run.end > input_len
                        {
                            return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                        }
                        removed = removed
                            .checked_add(run.end - run.start)
                            .ok_or_else(|| ctx.host.reject(NativeViolation::ArithmeticOverflow))?;
                        previous_end = run.end;
                    }
                    if input_len.checked_sub(removed) != Some(output_end) {
                        return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                    }
                    let mut map = std::mem::take(&mut row.value);
                    let result = map.hide_runs(hidden_runs, ctx);
                    // Restore through this original borrow, even after Host has
                    // latched a fault. A charged lookup cannot restore on error.
                    row.value = map;
                    result?;
                    row.stage = stage;
                    row.stage_len = input_len;
                    return Ok(());
                }
                if !hidden_runs.is_empty() {
                    return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                }
                let index = payload.get() as usize - 1;
                let row = self
                    .payloads
                    .get_mut(index, |bytes| charge_host(ctx.host, bytes))?
                    .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?;
                if row.stage != stage {
                    row.stage = stage;
                    row.stage_len = row.value.bytes;
                }
                let raw = row.raw;
                let role = row.role;
                let stage_len = row.stage_len;
                let mut map = std::mem::take(&mut row.value);
                let result = (|| {
                    if kind == StageKind::Trim {
                        for (start, end) in [(input.end, map.bytes), (0, input.start)] {
                            if start == end {
                                continue;
                            }
                            if role == PayloadKind::Title {
                                map.hide(start, end, ctx)?;
                                continue;
                            }
                            let host = HostSnapshot {
                                source: ClaimSource::R(raw),
                                utf8_len: stage_len,
                                consumed_start: start,
                                consumed_end: end,
                                payload_role: Some(role),
                                role: payload_host(role),
                                phase: NativePhase::Metadata,
                            };
                            self.transform(
                                &mut map,
                                start,
                                end,
                                "",
                                TransformKind::Payload(kind),
                                stage,
                                host,
                                ctx,
                            )?;
                        }
                    } else {
                        if output_start.checked_add(value.len()) != Some(output_end) {
                            return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                        }
                        let width = input
                            .end
                            .checked_sub(input.start)
                            .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?;
                        let end = output_start
                            .checked_add(width)
                            .ok_or_else(|| ctx.host.reject(NativeViolation::ArithmeticOverflow))?;
                        let host = HostSnapshot {
                            source: ClaimSource::R(raw),
                            utf8_len: stage_len,
                            consumed_start: input.start,
                            consumed_end: input.end,
                            payload_role: Some(role),
                            role: payload_host(role),
                            phase: NativePhase::Metadata,
                        };
                        self.transform(
                            &mut map,
                            output_start,
                            end,
                            value,
                            TransformKind::Payload(kind),
                            stage,
                            host,
                            ctx,
                        )?;
                    }
                    Ok(())
                })();
                self.payloads
                    .get_mut(index, |bytes| charge_host(ctx.host, bytes))?
                    .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?
                    .value = map;
                result?;
            }
            F::PayloadEnd { payload, value } => {
                let row = self
                    .payloads
                    .get(payload.get() as usize - 1, |bytes| {
                        charge_host(ctx.host, bytes)
                    })?
                    .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?;
                let len = row
                    .value
                    .bytes
                    .checked_add(row.prefix.as_ref().map_or(0, |(_, text)| text.len()))
                    .ok_or_else(|| ctx.host.reject(NativeViolation::ArithmeticOverflow))?;
                if len != value.len() {
                    return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                }
            }
            F::Definition { .. } | F::Winner { .. } => {}
            F::ReferenceUse {
                node,
                definition,
                syntax,
            } => {
                let binding = self.syntax_mut(node, ctx)?;
                if binding.definition != Some(definition)
                    || binding.syntax != Some(syntax)
                    || binding.reference_use
                {
                    return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                }
                binding.reference_use = true;
            }
            F::Extended(accepted) => {
                let raw_bytes = accepted
                    .raw
                    .end
                    .checked_sub(accepted.raw.start)
                    .filter(|n| *n != 0)
                    .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?;
                if accepted.node == accepted.label {
                    return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                }
                let label = self
                    .nodes
                    .get(accepted.label.get() as usize - 1, |bytes| {
                        charge_host(ctx.host, bytes)
                    })?
                    .and_then(|n| n.value)
                    .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?;
                let label = self
                    .values
                    .get(label.get() as usize - 1, |bytes| {
                        charge_host(ctx.host, bytes)
                    })?
                    .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?;
                ctx.scan(std::mem::size_of::<MappedValue>() + std::mem::size_of::<Atom>())?;
                if accepted.kind != super::g4::ExtendedKind::Email
                    && (label.bytes != raw_bytes
                        || label.atoms.len() != 1
                        || label.atoms[0].source != accepted.raw
                        || label.atoms[0].bytes != raw_bytes
                        || label.atoms[0].proof.is_some()
                        || label.atoms[0].hidden_syntax)
                {
                    return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                }
                let payload = self
                    .payloads
                    .get(accepted.destination.get() as usize - 1, |bytes| {
                        charge_host(ctx.host, bytes)
                    })?
                    .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?;
                let prefix = payload.prefix.as_ref().map(|_| payload.prefix_kind);
                if payload.role != PayloadKind::Destination
                    || payload.raw != accepted.raw
                    || payload.value.bytes != label.bytes
                    || match accepted.kind {
                        super::g4::ExtendedKind::Www => {
                            prefix != Some(super::GeneratedPrefix::Http)
                        }
                        super::g4::ExtendedKind::Url => prefix.is_some(),
                        super::g4::ExtendedKind::Email => {
                            prefix != Some(super::GeneratedPrefix::Mailto)
                        }
                    }
                {
                    return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                }
                if accepted.kind == super::g4::ExtendedKind::Email {
                    if label.bytes == 0 || label.atoms.len() != payload.value.atoms.len() {
                        return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                    }
                    let mut covered = accepted.raw.start;
                    for (a, b) in label.atoms.iter().zip(payload.value.atoms.iter()) {
                        ctx.event()?;
                        ctx.scan(2 * std::mem::size_of::<Atom>())?;
                        if a.bytes == 0
                            || a.hidden_syntax
                            || a.source.buffer != accepted.raw.buffer
                            || a.source.start != covered
                            || a.source.end <= a.source.start
                            || a.source != b.source
                            || a.bytes != b.bytes
                            || a.proof != b.proof
                            || a.hidden_syntax != b.hidden_syntax
                        {
                            return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                        }
                        covered = a.source.end;
                    }
                    if covered != accepted.raw.end {
                        return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                    }
                }
                let binding = self.syntax_mut(accepted.node, ctx)?;
                if binding.extended.is_some()
                    || binding.syntax != Some(accepted.raw)
                    || binding.label != Some(accepted.raw)
                    || binding.destination != Some(accepted.destination)
                    || binding.title.is_some()
                    || binding.definition.is_some()
                {
                    return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                }
                binding.extended = Some(accepted);
            }
            F::Link {
                node,
                syntax,
                label,
                image,
                wiki,
                destination,
                title,
                definition,
            } => {
                let binding = self.syntax_mut(node, ctx)?;
                binding.syntax = Some(syntax);
                binding.label = Some(label);
                binding.wiki = wiki;
                binding.destination = destination;
                binding.title = title;
                binding.definition = definition;
                if !image {
                    self.claim_r(node, syntax, ClaimKind::Link, ctx)?;
                }
            }
            #[cfg(test)]
            F::FinalBegin { .. }
            | F::FinalEnter { .. }
            | F::FinalExit { .. }
            | F::FinalSeal { .. } => {
                return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
            }
        }
        Ok(())
    }
}

impl<H: Host> Context<'_, H> {
    /// Resolve one scanner-accepted raw byte through one existing Copy piece.
    /// This returns a P coordinate, never a new source or grammar capability.
    pub(crate) fn accepted_copy_piece(&mut self, source: RSpan) -> Result<PSpan, H::Error> {
        let result = (|| {
            self.require_grammar()?;
            if !self.capture || self.is_shadow() || source.end.checked_sub(source.start) != Some(1)
            {
                return Err(self.host.reject(NativeViolation::InvalidProvenance));
            }
            let index = {
                let buffer = self
                    .mappings
                    .buffers
                    .get(source.buffer.get() as usize - 1, |n| {
                        charge_host(self.host, n)
                    })?
                    .ok_or_else(|| self.host.reject(NativeViolation::InvalidProvenance))?;
                if source.end > buffer.len {
                    return Err(self.host.reject(NativeViolation::InvalidProvenance));
                }
                let mut lo = 0;
                let mut hi = buffer.pieces.len();
                while lo < hi {
                    self.host.work(super::WorkDelta::Events(1))?;
                    self.host.work(super::WorkDelta::Scan(
                        std::mem::size_of::<BufferPiece>() as u64
                    ))?;
                    let middle = lo + (hi - lo) / 2;
                    if buffer.pieces[middle].r.end <= source.start {
                        lo = middle + 1;
                    } else {
                        hi = middle;
                    }
                }
                lo
            };
            let piece = self.transport_piece(source.buffer, index)?;
            if piece.kind != AppendKind::Copy
                || piece.r.start > source.start
                || source.end > piece.r.end
            {
                return Err(self.host.reject(NativeViolation::InvalidProvenance));
            }
            let start = piece
                .p
                .start
                .checked_add(source.start - piece.r.start)
                .ok_or_else(|| self.host.reject(NativeViolation::ArithmeticOverflow))?;
            let end = start
                .checked_add(1)
                .ok_or_else(|| self.host.reject(NativeViolation::ArithmeticOverflow))?;
            if end > piece.p.end {
                return Err(self.host.reject(NativeViolation::InvalidProvenance));
            }
            Ok(PSpan { start, end })
        })();
        if result.is_err() {
            self.final_phase = super::FinalPhase::Failed;
        }
        result
    }

    fn transport_start(
        &mut self,
        destination: RSpan,
        source: RSpan,
        expected_source: usize,
        expected_output: usize,
    ) -> Result<(usize, NativeNodeId), H::Error> {
        self.require_grammar()?;
        if !self.direct
            || destination.buffer == source.buffer
            || source.end.checked_sub(source.start) != Some(expected_source)
            || destination.end.checked_sub(destination.start) != Some(expected_output)
        {
            return Err(self.host.reject(NativeViolation::InvalidProvenance));
        }
        let buffer = self
            .mappings
            .buffers
            .get(destination.buffer.get() as usize - 1, |n| {
                charge_host(self.host, n)
            })?
            .ok_or_else(|| self.host.reject(NativeViolation::InvalidProvenance))?;
        if buffer.sealed || buffer.len != destination.start {
            return Err(self.host.reject(NativeViolation::InvalidProvenance));
        }
        let owner = buffer.owner;
        let buffer = self
            .mappings
            .buffers
            .get(source.buffer.get() as usize - 1, |n| {
                charge_host(self.host, n)
            })?
            .ok_or_else(|| self.host.reject(NativeViolation::InvalidProvenance))?;
        if source.end > buffer.len {
            return Err(self.host.reject(NativeViolation::InvalidProvenance));
        }
        let mut lo = 0;
        let mut hi = buffer.pieces.len();
        while lo < hi {
            self.host.work(super::WorkDelta::Events(1))?;
            self.host.work(super::WorkDelta::Scan(
                std::mem::size_of::<BufferPiece>() as u64
            ))?;
            let middle = lo + (hi - lo) / 2;
            let end = buffer.pieces[middle].r.end;
            if end < source.start || (end == source.start && source.start != source.end) {
                lo = middle + 1;
            } else {
                hi = middle;
            }
        }
        Ok((lo, owner))
    }

    fn transport_piece(&mut self, buffer: BufferId, index: usize) -> Result<BufferPiece, H::Error> {
        let value = self
            .mappings
            .buffers
            .get(buffer.get() as usize - 1, |n| charge_host(self.host, n))?
            .and_then(|b| b.pieces.get(index))
            .copied()
            .ok_or_else(|| self.host.reject(NativeViolation::InvalidProvenance))?;
        self.host.work(super::WorkDelta::Events(1))?;
        self.host.work(super::WorkDelta::Copy(
            std::mem::size_of::<BufferPiece>() as u64
        ))?;
        Ok(value)
    }

    /// Transports an actual, already charged string copy; it does not read text.
    pub(crate) fn transport_append_from_buffer(
        &mut self,
        destination: RSpan,
        source: RSpan,
    ) -> Result<(), H::Error> {
        if !self.capture {
            return Ok(());
        }
        let result = (|| {
            let count = source
                .end
                .checked_sub(source.start)
                .ok_or_else(|| self.host.reject(NativeViolation::InvalidProvenance))?;
            let (mut index, _) = self.transport_start(destination, source, count, count)?;
            if count == 0 {
                let piece = self.transport_piece(source.buffer, index)?;
                let p = match piece.kind {
                    AppendKind::Copy
                        if piece.r.start <= source.start && source.start <= piece.r.end =>
                    {
                        piece.p.start.checked_add(source.start - piece.r.start)
                    }
                    _ if source.start == piece.r.start => Some(piece.p.start),
                    _ if source.start == piece.r.end => Some(piece.p.end),
                    _ => None,
                }
                .ok_or_else(|| self.host.reject(NativeViolation::InvalidProvenance))?;
                return self.fact(AcceptedFact::Append {
                    span: destination,
                    source: PSpan { start: p, end: p },
                    kind: AppendKind::Copy,
                });
            }
            let mut cursor = source.start;
            while cursor < source.end {
                let piece = self.transport_piece(source.buffer, index)?;
                let start = cursor.max(piece.r.start);
                let end = source.end.min(piece.r.end);
                if start != cursor || start >= end {
                    return Err(self.host.reject(NativeViolation::InvalidProvenance));
                }
                let p = match piece.kind {
                    AppendKind::Copy => PSpan {
                        start: piece
                            .p
                            .start
                            .checked_add(start - piece.r.start)
                            .ok_or_else(|| self.host.reject(NativeViolation::ArithmeticOverflow))?,
                        end: piece
                            .p
                            .start
                            .checked_add(end - piece.r.start)
                            .ok_or_else(|| self.host.reject(NativeViolation::ArithmeticOverflow))?,
                    },
                    _ if start == piece.r.start && end == piece.r.end => piece.p,
                    _ => return Err(self.host.reject(NativeViolation::InvalidProvenance)),
                };
                let output = RSpan {
                    buffer: destination.buffer,
                    start: destination
                        .start
                        .checked_add(start - source.start)
                        .ok_or_else(|| self.host.reject(NativeViolation::ArithmeticOverflow))?,
                    end: destination
                        .start
                        .checked_add(end - source.start)
                        .ok_or_else(|| self.host.reject(NativeViolation::ArithmeticOverflow))?,
                };
                self.fact(AcceptedFact::Append {
                    span: output,
                    source: p,
                    kind: piece.kind,
                })?;
                cursor = end;
                index += 1;
            }
            Ok(())
        })();
        if result.is_err() {
            self.final_phase = super::FinalPhase::Failed;
        }
        result
    }

    /// Only transports the scanner's accepted two-byte pipe operation.
    pub(crate) fn transport_table_pipe(
        &mut self,
        destination: RSpan,
        source: RSpan,
    ) -> Result<(), H::Error> {
        if !self.capture {
            return Ok(());
        }
        let result = (|| {
            let (index, owner) = self.transport_start(destination, source, 2, 1)?;
            if self
                .mappings
                .g3
                .kind(owner, |n| charge_host(self.host, n))?
                != Some(super::NativeKind::TableCell)
            {
                return Err(self.host.reject(NativeViolation::InvalidProvenance));
            }
            let piece = self.transport_piece(source.buffer, index)?;
            if piece.kind != AppendKind::Copy
                || piece.r.start > source.start
                || piece.r.end < source.end
            {
                return Err(self.host.reject(NativeViolation::InvalidProvenance));
            }
            let p = PSpan {
                start: piece
                    .p
                    .start
                    .checked_add(source.start - piece.r.start)
                    .ok_or_else(|| self.host.reject(NativeViolation::ArithmeticOverflow))?,
                end: piece
                    .p
                    .start
                    .checked_add(source.end - piece.r.start)
                    .ok_or_else(|| self.host.reject(NativeViolation::ArithmeticOverflow))?,
            };
            self.fact(AcceptedFact::Append {
                span: destination,
                source: p,
                kind: AppendKind::TableEscapedPipe,
            })?;
            self.mutate_mappings(|mappings, access| {
                let index = mappings.claims.len();
                mappings.claim_r(owner, source, ClaimKind::Table, access)?;
                if mappings.table_pipes.len() != 0 {
                    let previous = mappings
                        .table_pipes
                        .get(mappings.table_pipes.len() - 1, |n| {
                            charge_host(access.host, n)
                        })?
                        .ok_or_else(|| access.host.reject(NativeViolation::InvalidProvenance))?;
                    access.host.work(super::WorkDelta::Scan(
                        std::mem::size_of::<TablePipeBinding>() as u64,
                    ))?;
                    if previous.destination.buffer.get() > destination.buffer.get()
                        || (previous.destination.buffer == destination.buffer
                            && previous.destination.end > destination.start)
                    {
                        return Err(access.host.reject(NativeViolation::InvalidProvenance));
                    }
                }
                mappings.table_pipes.push(
                    TablePipeBinding {
                        destination,
                        claim: index,
                    },
                    access.host,
                )
            })
        })();
        if result.is_err() {
            self.final_phase = super::FinalPhase::Failed;
        }
        result
    }
}

impl<L> Mappings<L> {
    fn checked_buffer<H: Host<Lease = L>>(
        &self,
        span: RSpan,
        ctx: &mut MappingAccess<'_, H>,
    ) -> Result<NativeNodeId, H::Error> {
        let buffer = self
            .buffers
            .get(span.buffer.get() as usize - 1, |bytes| {
                charge_host(ctx.host, bytes)
            })?
            .ok_or_else(|| ctx.host.reject(NativeViolation::InvalidProvenance))?;
        ctx.host
            .work(super::WorkDelta::Scan(std::mem::size_of::<RSpan>() as u64))?;
        if span.start > span.end || span.end > buffer.len {
            return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
        }
        Ok(buffer.owner)
    }

    fn check_g3<H: Host<Lease = L>>(
        &mut self,
        fact: super::g3::Fact,
        ctx: &mut MappingAccess<'_, H>,
    ) -> Result<(), H::Error> {
        use super::g3::Fact;
        match fact {
            Fact::Table {
                node, delimiter, ..
            } => {
                self.node_mut(node, ctx)?;
                if self.checked_buffer(delimiter, ctx)? != node {
                    return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                }
            }
            Fact::Alignment {
                table,
                delimiter_cell,
                ..
            } => {
                self.node_mut(table, ctx)?;
                self.checked_buffer(delimiter_cell, ctx)?;
            }
            Fact::Row {
                node, table, raw, ..
            } => {
                if self.node_mut(node, ctx)?.birth_parent != Some(table) {
                    return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                }
                self.checked_buffer(raw, ctx)?;
            }
            Fact::Cell {
                node,
                row,
                raw,
                content,
                ..
            } => {
                if self.node_mut(node, ctx)?.birth_parent != Some(row) {
                    return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                }
                self.checked_buffer(raw, ctx)?;
                if self.checked_buffer(
                    RSpan {
                        buffer: content,
                        start: 0,
                        end: 0,
                    },
                    ctx,
                )? != node
                {
                    return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                }
            }
            Fact::Task {
                node,
                item,
                paragraph,
                marker,
                spacer,
                ..
            } => {
                if self.node_mut(node, ctx)?.birth_parent != Some(item)
                    || self.node_mut(paragraph, ctx)?.birth_parent != Some(item)
                    || self.checked_buffer(marker, ctx)? != paragraph
                    || self.checked_buffer(spacer, ctx)? != paragraph
                    || marker.buffer != spacer.buffer
                    || marker.end.checked_sub(marker.start) != Some(3)
                    || marker.end != spacer.start
                    || spacer.start >= spacer.end
                {
                    return Err(ctx.host.reject(NativeViolation::InvalidProvenance));
                }
                self.node_mut(item, ctx)?;
            }
        }
        Ok(())
    }
}

#[cfg(test)]
mod memory_tests {
    use super::*;
    use crate::native::tests::MemoryHost;

    #[test]
    fn tail_replacement_writes_real_atoms_once_and_preserves_other_ranges() {
        let atom = |n: usize| Atom {
            source: RSpan {
                buffer: BufferId::from_raw(1).unwrap(),
                start: n,
                end: n + 1,
            },
            bytes: 1,
            proof: n.is_multiple_of(2).then_some(n),
            hidden_syntax: n.is_multiple_of(3),
        };
        let mut host = MemoryHost::new();
        let mut ctx = Context::new(&mut host, 20);
        let mut map = MappedValue::default();
        map.atoms.push(atom(0), &mut ctx.mapping_access()).unwrap();
        // Inline -> spilled growth at the tail, then shorter and empty tails.
        map.replace(
            1,
            1,
            &[atom(1), atom(2), atom(3)],
            &mut ctx.mapping_access(),
        )
        .unwrap();
        map.replace(2, 4, &[atom(4)], &mut ctx.mapping_access())
            .unwrap();
        assert_eq!(
            map.atoms.iter().map(|a| a.source.start).collect::<Vec<_>>(),
            [0, 1, 4]
        );
        assert_eq!(map.atoms[2].proof, Some(4));
        assert!(!map.atoms[2].hidden_syntax);
        // The overlapping non-tail path must retain its actual suffix.
        map.replace(1, 2, &[atom(5), atom(6)], &mut ctx.mapping_access())
            .unwrap();
        assert_eq!(
            map.atoms.iter().map(|a| a.source.start).collect::<Vec<_>>(),
            [0, 5, 6, 4]
        );
        assert!(map.atoms[2].hidden_syntax);
        map.replace(1, 4, &[], &mut ctx.mapping_access()).unwrap();
        assert_eq!(map.atoms.len(), 1);
        assert_eq!(map.atoms[0].source.start, 0);
        assert_eq!(map.atoms[0].proof, Some(0));
        map.atoms.take().discard(&mut ctx.mapping_access()).unwrap();
        assert_eq!(ctx.registry.test_counts().0, 0);
    }

    #[test]
    #[cfg(target_pointer_width = "64")]
    fn compact_claims_preserve_acceptance_snapshot_order_roles_and_wide_coordinates() {
        let wide = usize::try_from(u64::from(u32::MAX) + 64).unwrap();
        let mut host = MemoryHost::new();
        let mut ctx = Context::new(&mut host, wide + 512);
        let mut map = Mappings::default();
        let owner = NativeNodeId::from_raw(1).unwrap();
        let buffer = BufferId::from_raw(1).unwrap();
        map.buffers
            .push(
                BufferMapping {
                    owner,
                    len: wide + 128,
                    sealed: false,
                    pieces: SmallValue::new(),
                },
                ctx.host,
            )
            .unwrap();
        map.action = 19;
        let r = RSpan {
            buffer,
            start: wide,
            end: wide + 3,
        };
        map.claim_r(
            owner,
            r,
            ClaimKind::Syntax(SyntaxRole::ReferenceDefinition),
            &mut ctx.mapping_access(),
        )
        .unwrap();
        map.claim_p(
            owner,
            PSpan {
                start: wide,
                end: wide + 3,
            },
            ClaimKind::Syntax(SyntaxRole::ListPrefix),
            &mut ctx.mapping_access(),
        )
        .unwrap();
        map.buffers
            .get_mut(0, |bytes| charge_host(ctx.host, bytes))
            .unwrap()
            .unwrap()
            .len += 256;
        let original = *map
            .claims
            .get(0, |bytes| charge_host(ctx.host, bytes))
            .unwrap()
            .unwrap();
        let p = *map
            .claims
            .get(1, |bytes| charge_host(ctx.host, bytes))
            .unwrap()
            .unwrap();
        assert_eq!(
            original.order,
            ClaimOrder {
                action: 19,
                within_action: 0
            }
        );
        assert_eq!(
            p.order,
            ClaimOrder {
                action: 19,
                within_action: 1
            }
        );
        let h = original.host();
        assert_eq!(h.role, HostRole::Block);
        assert_eq!(h.phase, NativePhase::Block);
        assert_eq!(h.payload_role, None);
        assert_eq!((h.consumed_start, h.consumed_end), (wide, wide + 3));
        assert_eq!(h.utf8_len, wide + 128);
        let ClaimSource::R(full) = h.source else {
            panic!("R domain changed")
        };
        assert_eq!(
            full,
            RSpan {
                buffer,
                start: 0,
                end: wide + 128
            }
        );
        let ClaimSource::P(full) = p.host().source else {
            panic!("P domain changed")
        };
        assert_eq!(
            full,
            PSpan {
                start: 0,
                end: wide + 512
            }
        );
    }

    #[test]
    fn compact_claim_cannot_discard_payload_or_nonfull_host_authority() {
        for bad_payload in [false, true] {
            let mut host = MemoryHost::new();
            let mut ctx = Context::new(&mut host, 10);
            let source = ClaimSource::P(PSpan { start: 2, end: 4 });
            let h = HostSnapshot {
                source: ClaimSource::P(PSpan {
                    start: if bad_payload { 0 } else { 1 },
                    end: 10,
                }),
                utf8_len: 10,
                consumed_start: 2,
                consumed_end: 4,
                payload_role: bad_payload.then_some(PayloadKind::Title),
                role: HostRole::Block,
                phase: NativePhase::Block,
            };
            assert!(
                Claim::new(
                    NativeNodeId::from_raw(1).unwrap(),
                    ClaimOrder {
                        action: 1,
                        within_action: 0
                    },
                    ClaimKind::Whitespace,
                    source,
                    h,
                    &mut ctx.mapping_access()
                )
                .is_err()
            );
        }
    }
}
